// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.zip.CRC32C;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FrontierStatisticsManifestVersionTest {

	@Test
	void publishedStatisticsManifestsUseVersionSix(@TempDir Path directory) throws Exception {
		FrontierStatisticsManifestStore store = new FrontierStatisticsManifestStore(
				directory, NioFrontierFileOps.INSTANCE);
		store.publish(manifest());
		assertEquals(manifest(), store.loadCurrent());

		byte[] encoded = Files.readAllBytes(directory.resolve("manifest-0000000000000000001.fs2m"));
		assertEquals(6, ByteBuffer.wrap(encoded).order(ByteOrder.BIG_ENDIAN).getInt(Long.BYTES),
				"manifest version 6 fences the removed shard ordinals and compact delta coordinates");
	}

	@Test
	void olderStatisticsManifestVersionsAreRejected(@TempDir Path directory) throws Exception {
		FrontierStatisticsManifestStore store = new FrontierStatisticsManifestStore(
				directory, NioFrontierFileOps.INSTANCE);
		store.publish(manifest());
		Path path = directory.resolve("manifest-0000000000000000001.fs2m");
		byte[] encoded = Files.readAllBytes(path);

		for (int version : new int[] { 4, 5 }) {
			ByteBuffer.wrap(encoded).order(ByteOrder.BIG_ENDIAN).putInt(Long.BYTES, version);
			CRC32C checksum = new CRC32C();
			checksum.update(encoded, 0, encoded.length - Integer.BYTES);
			ByteBuffer.wrap(encoded)
					.order(ByteOrder.BIG_ENDIAN)
					.putInt(encoded.length - Integer.BYTES, (int) checksum.getValue());
			Files.write(path, encoded);
			assertThrows(IOException.class, () -> store.load(1L),
					() -> "manifest version " + version + " must be incompatible");
		}
	}

	private static FrontierStatisticsManifest manifest() {
		FrontierStatisticsShardDescriptor descriptor = new FrontierStatisticsShardDescriptor(
				0, FrontierStatisticsTier.EXACT_AND_LINEAR, true, "generation-0000000000000000001-shard-00000.fs2s",
				FrontierStatisticsShard.HEADER_BYTES, 0L);
		return new FrontierStatisticsManifest(1L, -1L, 0L, 0L, 0L, 1L, 0L, List.of(descriptor));
	}
}
